Shopware.Component.register('example-parent-detail', {
    template: '<div><mt-text-field v-model="parent.name"/><mt-text-field v-model="settings.note"/></div>',
    inject: ['repositoryFactory'],
    props: { parent: { type: Object, required: true }, settings: { type: Object, required: true } },
    methods: {
        async onSave() {
            const repository = this.repositoryFactory.create('example_settings');
            await repository.save(this.settings, Shopware.Context.api);
            this.$emit('saved');
        },
    },
});

